export const LIBRARY = Object.fromEntries(CATALOG.map((d) => [String(d.id), d])) as Record<
  string,
  Definition
>;
export function definition(kind: Kind): Definition {
  const d = Object.hasOwn(LIBRARY, String(kind)) ? LIBRARY[String(kind)] : undefined;
  if (!d) throw new Error(`未知棋子：${kind}`);
  return d;
}
export const SUMMON_POOL: Kind[] = Array.from({ length: 26 }, (_, i) => i + 1);
export const ULTIMATE_POOL: Kind[] = Array.from({ length: 28 }, (_, i) => `u${i + 1}` as Kind);
export const isStored = (d: Definition) =>
  d.spell !== undefined || d.weapon !== undefined || !!d.aura || d.tier === 'shrine';
